import{_ as e,o as i,c as a,ao as d}from"./chunks/framework.CWHsw1fv.js";const y=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":null}'),s={name:"benchmarks.md"};function l(r,t,n,h,g,o){return i(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h1><p>Reproduce with <code>julia --project=bench bench/headtohead.jl</code>. Every sample is written to <code>bench/results/headtohead.json</code>.</p><h2 id="Speed,-against-libosqp-0.6.2" tabindex="-1">Speed, against libosqp 0.6.2 <a class="header-anchor" href="#Speed,-against-libosqp-0.6.2" aria-label="Permalink to &quot;Speed, against libosqp 0.6.2 {#Speed,-against-libosqp-0.6.2}&quot;">​</a></h2><p>PureOSQP versus OSQP.jl 0.8.1 (libosqp 0.6.2) on dense random QPs, <code>eps_abs = eps_rel = 1e-6</code>, single-threaded BLAS, adaptive ρ pinned to a 50-iteration interval on both sides so the comparison is deterministic.</p><table tabindex="0"><thead><tr><th style="text-align:right;">n</th><th style="text-align:right;">m</th><th style="text-align:right;">PureOSQP</th><th style="text-align:right;">libosqp 0.6.2</th><th style="text-align:right;">speedup</th><th style="text-align:right;">iters (PureOSQP / C)</th><th style="text-align:right;">objective rel. Δ</th></tr></thead><tbody><tr><td style="text-align:right;">10</td><td style="text-align:right;">20</td><td style="text-align:right;">0.153 ms</td><td style="text-align:right;">0.081 ms</td><td style="text-align:right;">0.53×</td><td style="text-align:right;">100 / 100</td><td style="text-align:right;">3.8e-15</td></tr><tr><td style="text-align:right;">25</td><td style="text-align:right;">50</td><td style="text-align:right;">0.986 ms</td><td style="text-align:right;">1.67 ms</td><td style="text-align:right;">1.69×</td><td style="text-align:right;">675 / 675</td><td style="text-align:right;">1.4e-15</td></tr><tr><td style="text-align:right;">50</td><td style="text-align:right;">100</td><td style="text-align:right;">2.71 ms</td><td style="text-align:right;">5.81 ms</td><td style="text-align:right;">2.14×</td><td style="text-align:right;">900 / 900</td><td style="text-align:right;">1.8e-15</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">200</td><td style="text-align:right;">7.90 ms</td><td style="text-align:right;">20.9 ms</td><td style="text-align:right;">2.65×</td><td style="text-align:right;">850 / 850</td><td style="text-align:right;">1.3e-15</td></tr><tr><td style="text-align:right;">200</td><td style="text-align:right;">400</td><td style="text-align:right;">38.4 ms</td><td style="text-align:right;">130 ms</td><td style="text-align:right;">3.39×</td><td style="text-align:right;">1175 / 1175</td><td style="text-align:right;">4.4e-15</td></tr><tr><td style="text-align:right;">400</td><td style="text-align:right;">800</td><td style="text-align:right;">134 ms</td><td style="text-align:right;">1747 ms</td><td style="text-align:right;">13.0×</td><td style="text-align:right;">625 / 625</td><td style="text-align:right;">3.9e-15</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">50</td><td style="text-align:right;">1.63 ms</td><td style="text-align:right;">1.17 ms</td><td style="text-align:right;">0.72×</td><td style="text-align:right;">50 / 50</td><td style="text-align:right;">4.4e-15</td></tr><tr><td style="text-align:right;">200</td><td style="text-align:right;">100</td><td style="text-align:right;">5.41 ms</td><td style="text-align:right;">16.6 ms</td><td style="text-align:right;">3.07×</td><td style="text-align:right;">50 / 50</td><td style="text-align:right;">1.1e-14</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">1000</td><td style="text-align:right;">191 ms</td><td style="text-align:right;">902 ms</td><td style="text-align:right;">4.71×</td><td style="text-align:right;">7475 / 7475</td><td style="text-align:right;">2.6e-11</td></tr><tr><td style="text-align:right;">200</td><td style="text-align:right;">2000</td><td style="text-align:right;">299 ms</td><td style="text-align:right;">2044 ms</td><td style="text-align:right;">6.84×</td><td style="text-align:right;">3025 / 3025</td><td style="text-align:right;">7.1e-15</td></tr></tbody></table><h2 id="Agreement,-against-libosqp-1.x" tabindex="-1">Agreement, against libosqp 1.x <a class="header-anchor" href="#Agreement,-against-libosqp-1.x" aria-label="Permalink to &quot;Agreement, against libosqp 1.x {#Agreement,-against-libosqp-1.x}&quot;">​</a></h2><p><code>OSQP.jl</code> wraps 0.6.2 only. <code>bench/headtohead_v1.jl</code> compares against <strong>libosqp 1.x</strong> through a subprocess oracle (see <code>bench/oracle_v1/README.md</code>); it reports agreement, not timing, because each oracle call pays interpreter startup.</p><table tabindex="0"><thead><tr><th style="text-align:right;">n</th><th style="text-align:right;">m</th><th style="text-align:right;">status</th><th style="text-align:right;">iters (PureOSQP / 1.x)</th><th style="text-align:right;">objective rel. Δ</th></tr></thead><tbody><tr><td style="text-align:right;">10</td><td style="text-align:right;">20</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">125 / 125</td><td style="text-align:right;">0.0</td></tr><tr><td style="text-align:right;">25</td><td style="text-align:right;">50</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">300 / 300</td><td style="text-align:right;">1.5e-15</td></tr><tr><td style="text-align:right;">50</td><td style="text-align:right;">100</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">1400 / 1400</td><td style="text-align:right;">8.1e-16</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">200</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">2625 / 2625</td><td style="text-align:right;">2.5e-15</td></tr><tr><td style="text-align:right;">200</td><td style="text-align:right;">400</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">700 / 700</td><td style="text-align:right;">3.4e-15</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">50</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">50 / 50</td><td style="text-align:right;">5.1e-16</td></tr><tr><td style="text-align:right;">50</td><td style="text-align:right;">500</td><td style="text-align:right;">solved / solved</td><td style="text-align:right;">1875 / 1875</td><td style="text-align:right;">2.4e-13</td></tr></tbody></table><p>Identical iteration counts against both the version this port was transcribed from and the current one.</p><h2 id="How-to-read-this" tabindex="-1">How to read this <a class="header-anchor" href="#How-to-read-this" aria-label="Permalink to &quot;How to read this {#How-to-read-this}&quot;">​</a></h2><p><strong>What the matching iteration counts do and do not show.</strong> They mean the equilibration, the ρ schedule and the termination tests track the reference implementation, which is the part of OSQP&#39;s behavior a port most easily gets subtly wrong. But the count is <em>quantized</em>: with <code>check_termination = 25</code>, matching counts say both solvers crossed the threshold within the same 25-iteration window, not that the iterates agree. The evidence that they agree iterate-by-iterate is separate — the transcription test, which matches to <code>1e-10</code> over the first 25 iterations with adaptive ρ disabled — and the evidence about the returned <code>y</code> is separate again, since the objective does not contain <code>y</code>. That one comes from the referee.</p><p>The corpus behind these numbers is feasible, bounded, cold-started, two-sided and dense. Infeasibility detection, warm starting, polishing, <code>±Inf</code> bounds, equality rows and degenerate <code>P</code> are covered in the test suite, not here.</p><p><strong>The timings are not a claim that this solver is better than OSQP.</strong> These are dense problems, which is the reference implementation&#39;s worst case: it is a <em>sparse</em> solver being handed dense matrices, so it pays sparse-format overhead and scalar sparse LDLᵀ where PureOSQP gets BLAS-3 dense Cholesky. The right reading is a <em>storage-format</em> comparison, not a solver-quality one. On genuinely sparse problems the reference implementation is expected to win, and PureOSQP has no answer for a sparse <code>A</code> beyond treating it as dense. PureOSQP already loses here on the smallest problems (0.53× at <code>n = 10</code>), where setup dominates, and at <code>n = 100, m = 50</code>, where the reduced system is barely smaller than the full one.</p><h2 id="Linear-system-backend" tabindex="-1">Linear-system backend <a class="header-anchor" href="#Linear-system-backend" aria-label="Permalink to &quot;Linear-system backend {#Linear-system-backend}&quot;">​</a></h2><p><code>bench/kkt_backend.jl</code> reproduces the cost and accuracy comparison between the reduced Cholesky and the full-KKT Bunch-Kaufman factorization described under <a href="/PureOSQP.jl/dev/algorithm#The-linear-system">Algorithm</a>, including the near-parallel-row family that equilibration cannot fix.</p><h2 id="Sequential-re-solves" tabindex="-1">Sequential re-solves <a class="header-anchor" href="#Sequential-re-solves" aria-label="Permalink to &quot;Sequential re-solves {#Sequential-re-solves}&quot;">​</a></h2><p><code>P</code> and <code>A</code> fixed, <code>q</code>, <code>l</code> and <code>u</code> changing every step — the receding-horizon loop OSQP is most used for. 20 solves per case, <code>eps_abs = eps_rel = 1e-6</code>. libosqp 1.x is timed inside its own process, so interpreter startup and the JSON round trip are excluded. Reproduce with <code>julia --project=bench bench/update_bench.jl</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">n</th><th style="text-align:right;">m</th><th style="text-align:right;"><code>update!</code></th><th style="text-align:right;">fresh <code>setup</code> each step</th><th style="text-align:right;">saved</th><th style="text-align:right;">libosqp 1.x</th><th style="text-align:right;">ratio</th><th style="text-align:right;">factorizations</th><th style="text-align:right;">objective Δ</th></tr></thead><tbody><tr><td style="text-align:right;">10</td><td style="text-align:right;">20</td><td style="text-align:right;">2.00 ms</td><td style="text-align:right;">2.66 ms</td><td style="text-align:right;">1.33×</td><td style="text-align:right;">1.82 ms</td><td style="text-align:right;"><strong>0.91×</strong></td><td style="text-align:right;">8</td><td style="text-align:right;">1.5e-14</td></tr><tr><td style="text-align:right;">25</td><td style="text-align:right;">50</td><td style="text-align:right;">5.38 ms</td><td style="text-align:right;">11.3 ms</td><td style="text-align:right;">2.10×</td><td style="text-align:right;">9.77 ms</td><td style="text-align:right;">1.82×</td><td style="text-align:right;">14</td><td style="text-align:right;">4.3e-12</td></tr><tr><td style="text-align:right;">50</td><td style="text-align:right;">100</td><td style="text-align:right;">26.1 ms</td><td style="text-align:right;">45.3 ms</td><td style="text-align:right;">1.73×</td><td style="text-align:right;">59.3 ms</td><td style="text-align:right;">2.27×</td><td style="text-align:right;">7</td><td style="text-align:right;">7.6e-14</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">200</td><td style="text-align:right;">157 ms</td><td style="text-align:right;">180 ms</td><td style="text-align:right;">1.15×</td><td style="text-align:right;">491 ms</td><td style="text-align:right;">3.13×</td><td style="text-align:right;">3</td><td style="text-align:right;">3.9e-13</td></tr><tr><td style="text-align:right;">200</td><td style="text-align:right;">400</td><td style="text-align:right;">634 ms</td><td style="text-align:right;">803 ms</td><td style="text-align:right;">1.27×</td><td style="text-align:right;">2420 ms</td><td style="text-align:right;">3.81×</td><td style="text-align:right;">1</td><td style="text-align:right;">1.9e-15</td></tr></tbody></table><p>&quot;Factorizations&quot; counts the whole 20-step sequence: one from <code>setup</code>, plus one per step whose constraint classification changed.</p><p>Two things worth reading off this. The saving from <code>update!</code> is bounded by how much of the run is setup: at <code>n = 200</code> the ADMM iterations dominate, so skipping 19 of 20 factorizations is worth only 1.27×, while at <code>n = 25</code> — short solves, setup a large share — it is 2.10×. And the factorization count is not always 1: equilibration rescales the bounds, so a row whose scaled gap <code>ũ - l̃</code> falls under <code>RHO_TOL</code> is reclassified as an equality and its <code>ρ</code> changes. That is upstream&#39;s rule, applied to the scaled bounds exactly as upstream applies it, and it means <code>update!</code> is not unconditionally factorization-free.</p><p>PureOSQP is slower than libosqp 1.x on the smallest case here, as it is in the single-solve comparison, for the same reason: at <code>n = 10</code> the per-solve overhead dominates and there is no dense-linear-algebra advantage to collect.</p>',21)])])}const x=e(s,[["render",l]]);export{y as __pageData,x as default};
